\[
P (y, \boldsymbol {t}, M | \boldsymbol {X}) = \underbrace {P (y | \boldsymbol {t} , \boldsymbol {X})} _ {\text { Species }} \cdot \underbrace {P (\boldsymbol {t} | M , \boldsymbol {X})} _ {\text { Traits }} \cdot \underbrace {P (M | \boldsymbol {X})} _ {\text { Segmentation }} \tag {1}
\]

\[
P (\boldsymbol {y} _ {s}, \boldsymbol {y} _ {t}, \boldsymbol {y} _ {c} | \boldsymbol {x}) = P (\boldsymbol {y} _ {s} | \boldsymbol {x}) \cdot P (\boldsymbol {y} _ {t} | \boldsymbol {y} _ {s}, \boldsymbol {x}) \cdot P (\boldsymbol {y} _ {c} | \boldsymbol {y} _ {t}, \boldsymbol {y} _ {s}, \boldsymbol {x}) \tag {2}
\]

\[
\boldsymbol {e} = \phi (\boldsymbol {f}) \in \mathbb {R} ^ {D \times H ^ {\prime} \times W ^ {\prime}} \tag {3}
\]

\[
\boldsymbol {l} _ {s} (k, h, w) = \frac {1}{\tau} \cdot \frac {\boldsymbol {e} (\cdot , h , w) ^ {\top} \boldsymbol {P} _ {k}}{\| \boldsymbol {e} (\cdot , h , w) \| _ {2} \cdot \| \boldsymbol {P} _ {k} \| _ {2}} \tag {4}
\]

\[
\hat {\boldsymbol {y}} _ {s} = \text { Upsample } (\boldsymbol {l} _ {s}) \in \mathbb {R} ^ {K \times H \times W}. \tag {5}
\]

\[
\mathcal {L} _ {\text { ortho }} = \frac {1}{K ^ {2}} \left\| \boldsymbol {P} _ {\text { norm }} \boldsymbol {P} _ {\text { norm }} ^ {\top} - \boldsymbol {I} _ {K} \right\| _ {F} ^ {2} \tag {6}
\]

\[
\boldsymbol {g} = \text { AdaptiveAvgPool2D } (\boldsymbol {f} _ {L}) \in \mathbb {R} ^ {C _ {L}} \tag {7}
\]

\[
\boldsymbol {p} = \text { AdaptiveMaxPool2D } (\boldsymbol {l} _ {s}) \in \mathbb {R} ^ {K}. \tag {8}
\]

\[
\boldsymbol {b} = [ \boldsymbol {g}; \boldsymbol {p} ^ {\text {detach}} ] \in \mathbb {R} ^ {C _ {L} + K} \tag {9}
\]

\[
\boldsymbol {h} _ {t} = \psi_ {t} (\boldsymbol {b}) \in \mathbb {R} ^ {d _ {t}}. \tag {10}
\]

\[
\dot {\boldsymbol {y}} _ {t} = \boldsymbol {W} _ {t} \boldsymbol {h} _ {t} + \boldsymbol {b} _ {t} \in \mathbb {R} ^ {T} \tag {11}
\]

\[
\boldsymbol {b} _ {c} = \left[ \boldsymbol {b}; \boldsymbol {h} _ {t} ^ {\text {detach}} \right] \in \mathbb {R} ^ {C _ {L} + K + d _ {t}} \tag {12}
\]

\[
\boldsymbol {h} _ {c} = \psi_ {c} (\boldsymbol {b} _ {c}) \in \mathbb {R} ^ {d _ {c}}. \tag {13}
\]

\[
\hat {\boldsymbol {y}} _ {c} = \boldsymbol {W} _ {c} \boldsymbol {h} _ {c} + \boldsymbol {\beta} _ {c} \in \mathbb {R} ^ {C} \tag {14}
\]

\[
p _ {i, k} = \frac {\exp (\hat {y} _ {s , i , k})}{\sum_ {j = 0} ^ {K - 1} \exp (\hat {y} _ {s , i , j})} \tag {15}
\]

\[
\mathcal {L} _ {s} ^ {\mathrm{CE}} = - \frac {1}{\sum_ {i \in \Omega} w _ {y _ {s , i}}} \sum_ {i \in \Omega} w _ {y _ {s, i}} \log (p _ {i, y _ {s, i}}) \tag {16}
\]

\[
\mathcal {L} _ {s} ^ {\text {Dice}} = 1 - \frac {1}{K} \sum_ {k = 0} ^ {K - 1} \frac {2 \sum_ {i \in \Omega} p _ {i , k} \cdot g _ {i , k}}{\sum_ {i \in \Omega} p _ {i , k} + \sum_ {i \in \Omega} g _ {i , k}} \tag {17}
\]

\[
\mathcal {L} _ {s} = \mathcal {L} _ {s} ^ {\mathrm{CE}} + \mathcal {L} _ {s} ^ {\mathrm{Dice}}. \tag {18}
\]

\[
\begin{array}{l} \mathcal {L} _ {t} = - \frac {1}{| \mathcal {M} |} \sum_ {j \in \mathcal {M}} \left[ y _ {t, j} \log \sigma (\hat {y} _ {t, j}) \right. \\ \left. + \left(1 - y _ {t, j}\right) \log \left(1 - \sigma \left(\hat {y} _ {t, j}\right)\right) \right] \tag {19} \\ \end{array}
\]

\[
\mathcal {L} _ {c} = - \sum_ {k = 1} ^ {C} \tilde {y} _ {c, k} \log (p _ {c, k}) \tag {20}
\]

\[
\tilde {y} _ {c, k} = \left\{ \begin{array}{l l} 1 - \epsilon , & \text { if } k = y _ {c} \\ \frac {\epsilon}{C - 1}, & \text { otherwise } \end{array} \right. \tag {21}
\]

\[
\mathcal {L} _ {\text { task }} = \sum_ {m \in \{s, t, c \}} \left(\exp (- \eta_ {m}) \mathcal {L} _ {m} + \eta_ {m}\right) \tag {22}
\]

\[
\mathcal {L} _ {\text { total }} = \mathcal {L} _ {\text { task }} + \lambda \mathcal {L} _ {\text { ortho }} \tag {23}
\]

\[
\mathrm{IoU} _ {k} = \frac {\mathrm{TP} _ {k}}{\mathrm{TP} _ {k} + \mathrm{FP} _ {k} + \mathrm{FN} _ {k}} \tag {24}
\]

\[
\mathrm{mIoU} = \frac {1}{K - 1} \sum_ {k = 1} ^ {K - 1} \mathrm{IoU} _ {k}. \tag {25}
\]

\[
\text { Precision } _ {j} = \frac {\mathrm{TP} _ {j}}{\mathrm{TP} _ {j} + \mathrm{FP} _ {j}} \tag {26}
\]

\[
\text { Recall } _ {j} = \frac {\mathrm{TP} _ {j}}{\mathrm{TP} _ {j} + \mathrm{FN} _ {j}} \tag {27}
\]

\[
\mathrm{F} 1 _ {j} = \frac {2 \cdot \text { Precision } _ {j} \cdot \text { Recall } _ {j}}{\text { Precision } _ {j} + \text { Recall } _ {j}}. \tag {28}
\]

\[
\mathrm{AP} _ {j} = \sum_ {k = 1} ^ {N} (R _ {k} - R _ {k - 1}) \cdot P _ {k} \tag {29}
\]

\[
\mathrm{mAP} = \frac {1}{T} \sum_ {j = 1} ^ {T} \mathrm{AP} _ {j}. \tag {30}
\]

\[
\text { Accuracy } = \frac {1}{N} \sum_ {i = 1} ^ {N} \mathbb {I} (\underset {k} {\operatorname{argmax}} \hat {y} _ {c, i, k} = y _ {c, i}) \tag {31}
\]
